SET FOREIGN_KEY_CHECKS=0;
DROP DATABASE IF EXISTS techconnect_douala;
CREATE DATABASE techconnect_douala;
USE techconnect_douala;

CREATE TABLE Technician (Technician_ID VARCHAR(20) PRIMARY KEY, Name VARCHAR(100), Email VARCHAR(100), Location VARCHAR(100), Service VARCHAR(100), Ratings DECIMAL(2,1));
CREATE TABLE Client (Client_ID VARCHAR(20) PRIMARY KEY, Name VARCHAR(100), Email VARCHAR(100), Location VARCHAR(100), Phone VARCHAR(20));
CREATE TABLE Services (Service_ID VARCHAR(20) PRIMARY KEY, Name VARCHAR(100), Category VARCHAR(50), Technician_ID VARCHAR(20), FOREIGN KEY (Technician_ID) REFERENCES Technician(Technician_ID));
CREATE TABLE Price (Price_ID VARCHAR(20) PRIMARY KEY, Amount INT, Category VARCHAR(50), Service_ID VARCHAR(20), FOREIGN KEY (Service_ID) REFERENCES Services(Service_ID));
CREATE TABLE Spare_Parts (Part_ID VARCHAR(20) PRIMARY KEY, Name VARCHAR(100), Category VARCHAR(50), Price_ID VARCHAR(20), Service_ID VARCHAR(20), FOREIGN KEY (Price_ID) REFERENCES Price(Price_ID), FOREIGN KEY (Service_ID) REFERENCES Services(Service_ID));
CREATE TABLE Transactions (Transaction_ID VARCHAR(20) PRIMARY KEY, Client_ID VARCHAR(20), Price_ID VARCHAR(20), Service_ID VARCHAR(20), Date DATE, FOREIGN KEY (Client_ID) REFERENCES Client(Client_ID), FOREIGN KEY (Price_ID) REFERENCES Price(Price_ID), FOREIGN KEY (Service_ID) REFERENCES Services(Service_ID));
CREATE TABLE Feedback (Feedback_ID VARCHAR(20) PRIMARY KEY, Client_ID VARCHAR(20), Technician_ID VARCHAR(20), Service_ID VARCHAR(20), Message TEXT, Rating INT, Date DATE, FOREIGN KEY (Client_ID) REFERENCES Client(Client_ID), FOREIGN KEY (Technician_ID) REFERENCES Technician(Technician_ID), FOREIGN KEY (Service_ID) REFERENCES Services(Service_ID));
CREATE TABLE Season (Season_ID VARCHAR(20) PRIMARY KEY, Name VARCHAR(100), Duration VARCHAR(50), Discount_Amount INT, Client_ID VARCHAR(20), Service_ID VARCHAR(20), Technician_ID VARCHAR(20), FOREIGN KEY (Client_ID) REFERENCES Client(Client_ID), FOREIGN KEY (Service_ID) REFERENCES Services(Service_ID), FOREIGN KEY (Technician_ID) REFERENCES Technician(Technician_ID));

